const starterAdventure:Adventure={destinationId:'ananthagiri',title:'Ananthagiri Hills',status:'Planned',progress:0,checkpoint:0,checklist:['Water · 2 litres per person','Trail shoes with grip','First-aid basics','Weather check from a reliable local source','Share route and return time with someone'],xp:0,votes:{'Aarav':'yes','Meera':'yes','Kabir':'maybe','You':'yes'},members:[{name:'You',fitness:'Easy',budget:'2000',activity:'Trek',availableHours:12},{name:'Aarav',fitness:'Easy',budget:'2000',activity:'Nature',availableHours:12},{name:'Meera',fitness:'Moderate',budget:'2000',activity:'Trek',availableHours:12},{name:'Kabir',fitness:'Experienced',budget:'2000',activity:'Nature',availableHours:12}],tasks:['Pick up reusable water bottles','Pack a small trail snack','Leave no trace: carry out all waste'],impact:0,date:nextSunday(),duration:'1 day',departureTime:'06:00',elapsedMinutes:0,twinFitness:'Easy',revision:1,scenarioLabel:'',contributions:[],history:[],completedQuestIds:[],questHistory:[],earnedBadges:[],preferences:initialPrefs};
function normalizeAdventure(value:Partial<Adventure>):Adventure {
  const merged={...starterAdventure,...value};
  const completedQuestIds=Array.isArray(value.completedQuestIds)?value.completedQuestIds:(Array.isArray(value.tasks)?value.tasks.filter(task=>task.startsWith('✓ ')).map(task=>task.replace(/^✓ /,'')):[]);
  const earnedBadges=Array.isArray(value.earnedBadges)?value.earnedBadges.slice():[];
  if(completedQuestIds.some(task=>/water|bottle/i.test(task))&&!earnedBadges.includes('Bottle carrier'))earnedBadges.push('Bottle carrier');
  if(completedQuestIds.some(task=>/waste|leave no trace/i.test(task))&&!earnedBadges.includes('Leave no trace'))earnedBadges.push('Leave no trace');
  if(value.progress===100&&!earnedBadges.includes('Trail finisher'))earnedBadges.push('Trail finisher');
  const persistedXP=Math.max(Number(value.xp)||0,completedQuestIds.length*25+(earnedBadges.includes('Trail finisher')?100:0));
  return {
    ...merged,
    checklist:Array.isArray(value.checklist)?value.checklist:starterAdventure.checklist,
    members:Array.isArray(value.members)?value.members.map(member=>({...member,availableHours:member.availableHours??12,mobility:member.mobility??''})):starterAdventure.members,
    votes:value.votes&&typeof value.votes==='object'?value.votes:starterAdventure.votes,
    tasks:Array.isArray(value.tasks)?value.tasks:starterAdventure.tasks,
    contributions:Array.isArray(value.contributions)?value.contributions:(value.impact? [{id:'legacy-impact',kind:'Previously logged demo actions',amount:value.impact,date:new Date().toISOString().slice(0,10),reported:true}]:[]),
    history:Array.isArray(value.history)?value.history:[],
    completedQuestIds,
    questHistory:Array.isArray(value.questHistory)?value.questHistory:[],
    earnedBadges,
    xp:persistedXP,
    elapsedMinutes:Number.isFinite(value.elapsedMinutes)?value.elapsedMinutes:0,
    revision:Number.isFinite(value.revision)?value.revision:1,
    departureTime:value.departureTime||'06:00',
  };
}
