  const [assistantInput,setAssistantInput]=useState('');
  const [assistantAction,setAssistantAction]=useState<{label:string;destinationId?:string;screen?:Screen;scenario?:string}|null>(null);
  const [printCard,setPrintCard]=useState(false);
  const [planScenario,setPlanScenario]=useState('');
  useEffect(()=>{localStorage.setItem('tv-prefs',JSON.stringify(prefs));},[prefs]);
