  const duplicateAdventure=()=>{const copy={...adventure,id:`adventure-${Date.now()}`,title:`${active.name} · copy`,status:'Planned',progress:0,checkpoint:0,elapsedMinutes:0,revision:1,history:[...(adventure.history||[]),'Duplicated from current plan']};setAdventure(copy);setSavedAdventures(list=>[copy,...list]);notify('Adventure duplicated');};
  const openSavedAdventure=(id:string)=>{const plan=savedAdventures.find(item=>item.id===id);if(!plan)return;setAdventure(plan);setPrefs(plan.preferences||{...prefs,date:plan.date||prefs.date,duration:plan.duration||prefs.duration,group:String(plan.members.length)});setScreen('My Adventures');notify(`${plan.title} opened`);};
